WITH promo_discount AS ( SELECT promo_sk, SUM(discount_amt) AS total_discount, SUM(sale_cnt) AS total_sales FROM ( SELECT cs.cs_promo_sk AS promo_sk, cs.cs_ext_discount_amt AS discount_amt, 1 AS sale_cnt FROM catalog_sales cs UNION ALL SELECT ss.ss_promo_sk AS promo_sk, ss.ss_ext_discount_amt AS discount_amt, 1 AS sale_cnt FROM store_sales ss ) d GROUP BY promo_sk ) SELECT p.p_promo_id, d.total_discount, d.total_sales, CASE WHEN d.total_sales = 0 THEN 0 ELSE d.total_discount / d.total_sales END AS avg_discount, CASE WHEN d.total_discount / NULLIF(d.total_sales, 0) > 50 THEN 'Very High' WHEN d.total_discount / NULLIF(d.total_sales, 0) > 20 THEN 'High' WHEN d.total_discount / NULLIF(d.total_sales, 0) > 5 THEN 'Medium' ELSE 'Low' END AS discount_category, DENSE_RANK() OVER (ORDER BY d.total_discount DESC) AS discount_rank FROM promo_discount d JOIN promotion p ON d.promo_sk = p.p_promo_sk ORDER BY discount_rank
